  specU:['specu','usl','上限','规格上限'], specL:['specl','lsl','下限','规格下限'], tolerance:['tolerance','tol','公差','公差带宽'],
  angle:['angle','角度'], station:['station','乘坐','乘座','座位','座椅','位置','穴位','工位','机位'], category:['category','类别','检测类别'],
  avg:['avg','average','平均','平均值'], max:['max','最大','最大值'], min:['min','最小','最小值'], gap:['gap','极差'], sigma:['sigma','σ','stdev','stddev','标准差'], sixSigma:['6sigma','6σ','sixsigma','重复性']
