    const m=parseRangeRC(range); if(!m) continue;
    if(m.r1!==block.headerRow || m.r2!==block.headerRow) continue;
    if(m.c2<firstCol || m.c1>lastCol) continue;
    const start=Math.max(firstCol,m.c1), end=Math.min(lastCol,m.c2);
    const label=String(sheet.cells[block.headerRow]?.[m.c1]??'').trim() || category || 'Item';
