  records:[],experience:[],recordCenterTab:'records',recordScope:'all',validationExpanded:false,before:null,after:null,beforeBuffer:null,afterBuffer:null,
  beforeFileName:'',afterFileName:'',selectedKey:null,toleranceRules:{},ignoredSheets:new Set(),
  filters:{angle:'全部',station:'全部',category:'全部',imageGroup:'全部',product:'全部',status:'全部'},onlyAnomalyHeatmap:true,
