function currentAnalysisId(){return normalizeAnalysisId(currentAnalysisName());}
function recordAnalysisId(record){return String(record?.analysisId||normalizeAnalysisId(record?.sourceFileName||'')||record?.projectId||'');}
function currentRecords(){const id=currentAnalysisId();return id?state.records.filter(r=>recordAnalysisId(r)===id):[];}

