async function init(){
  $('#btnSheetConfirm')?.addEventListener('click',confirmSheetImport);$('#btnSheetCancel')?.addEventListener('click',cancelSheetImport);$('#btnSheetReselect')?.addEventListener('click',reselectSheetConfirm);$('#btnSheetConfirmClose')?.addEventListener('click',cancelSheetImport);document.addEventListener('keydown',e=>{if(e.key==='Escape'&&state.pendingImport)cancelSheetImport();});
  $$('.tab').forEach(t=>t.addEventListener('click',()=>activate(t.dataset.panel)));$('#btnBeforeFile').addEventListener('click',()=>$('#beforeFileInput').click());$('#beforeFileInput').addEventListener('change',e=>loadFile(e.target.files[0],'before'));$('#afterFileInput').addEventListener('change',e=>loadFile(e.target.files[0],'after'));
  const drop=$('#beforeDrop');drop.addEventListener('dragover',e=>{e.preventDefault();drop.classList.add('drag')});drop.addEventListener('dragleave',()=>drop.classList.remove('drag'));drop.addEventListener('drop',e=>{e.preventDefault();drop.classList.remove('drag');loadFile(e.dataTransfer.files[0],'before')});
  $('#btnBack').addEventListener('click',()=>{if(history.length>1)history.back();else toast('独立 HTML 模式下没有上一页；整合进 AOI LAB 后此按钮返回工具箱。');});$('#btnExportBackup').addEventListener('click',exportBackup);$('#footerDataManage').addEventListener('click',()=>activate('records'));$('#btnRecords').addEventListener('click',()=>{state.recordCenterTab='records';state.recordScope='all';renderRecordCenter();activate('records');});$('#btnHelp').addEventListener('click',()=>{if(window.__AOI_REPEATABILITY_HELP__)window.__AOI_REPEATABILITY_HELP__();else alert('重复性分析：直接导入 .xlsx，文件名作为当前分析名称。导入后会自动检查结构、公差与 Excel 公式；只有发现问题时才在总览提示并可展开详情。测试记录和工程经验统一在记录中心查看。');});
  $('#backupFileInput').addEventListener('change',async e=>{try{const file=e.target.files[0];if(!file)return;const p=JSON.parse(await file.text());await importBackupPayload(p);await refreshLocalData();toast('备份已恢复');}catch(err){toast('导入备份失败：'+err.message);}});
  await refreshLocalData();renderAll();
}
init();

